from pathlib import Path
import hashlib,json,math
root=Path(__file__).parent
def read(name,expected=None):
 p=root/name;b=p.read_bytes()
 if expected:assert len(b)==expected[0] and hashlib.sha256(b).hexdigest()==expected[1]
 return json.loads(b)
def pin(name):
 p=root/name;b=p.read_bytes();return dict(path=str(p),bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
def q(v):return {name:math.ceil(v[name]['upperNs']/1e6) for name in ('p50','p95','p99')}
